-- The legacy node IDs and subscriptions remain readable; authentication is moved
-- out of their connection profiles. New catalog assignments never use user_id.
CREATE TABLE credential_material(id TEXT PRIMARY KEY,instance_id INTEGER REFERENCES instances(id),inbound_tag TEXT NOT NULL,core_client_ref TEXT NOT NULL,user_id INTEGER REFERENCES users(id),auth_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',source TEXT NOT NULL DEFAULT 'config',verified_at TEXT NOT NULL);
CREATE INDEX credential_inbound ON credential_material(instance_id,inbound_tag,core_client_ref);
INSERT INTO credential_material SELECT id,instance_id,inbound_tag,COALESCE(json_extract(effective_json,'$.user_key'),CAST(user_id AS TEXT)),user_id,json_object('uuid',COALESCE(json_extract(effective_json,'$.uuid'),''),'password',COALESCE(json_extract(effective_json,'$.password'),'')),CASE WHEN present=1 THEN 'available' ELSE 'source_missing' END,'legacy_config',updated_at FROM nodes;
UPDATE nodes SET discovered_json=json_remove(discovered_json,'$.uuid','$.password'),effective_json=json_remove(effective_json,'$.uuid','$.password'),overrides_json=json_remove(overrides_json,'$.uuid','$.password');
CREATE TABLE catalog_inbounds(id TEXT PRIMARY KEY,instance_id INTEGER NOT NULL REFERENCES instances(id),source_ref TEXT NOT NULL,tag TEXT NOT NULL,protocol TEXT NOT NULL,listen_address TEXT NOT NULL DEFAULT '',listen_port INTEGER NOT NULL,profile_json TEXT NOT NULL,structure_hash TEXT NOT NULL,config_hash TEXT NOT NULL,present INTEGER NOT NULL DEFAULT 1,review INTEGER NOT NULL DEFAULT 0,runtime_state TEXT NOT NULL DEFAULT 'unknown',discovered_at TEXT NOT NULL,UNIQUE(instance_id,tag,protocol));
CREATE TABLE node_endpoints(id TEXT PRIMARY KEY,name TEXT NOT NULL,profile_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
ALTER TABLE catalog_inbounds ADD COLUMN authentication_type TEXT NOT NULL DEFAULT 'unknown';
ALTER TABLE catalog_inbounds ADD COLUMN source_capabilities_json TEXT NOT NULL DEFAULT '{"configured_clients":"source_only","runtime_loaded":"unknown","dynamic_management":"unknown"}';
CREATE TABLE node_profiles(id TEXT PRIMARY KEY,inbound_id TEXT REFERENCES catalog_inbounds(id),endpoint_id TEXT REFERENCES node_endpoints(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',source_type TEXT NOT NULL CHECK(source_type IN ('discovered','manual')),profile_json TEXT NOT NULL DEFAULT '{}',overrides_json TEXT NOT NULL DEFAULT '{}',tags_json TEXT NOT NULL DEFAULT '[]',enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX node_profiles_inbound ON node_profiles(inbound_id);
INSERT INTO catalog_inbounds(id,instance_id,source_ref,tag,protocol,listen_port,profile_json,structure_hash,config_hash,present,discovered_at) SELECT 'legacy_'||MIN(id),instance_id,'legacy',inbound_tag,protocol,COALESCE(json_extract(discovered_json,'$.listen_port'),0),json_remove(discovered_json,'$.name','$.user_key','$.uuid','$.password'),'legacy',source_hash,MAX(present),updated_at FROM nodes GROUP BY instance_id,inbound_tag,protocol;
INSERT INTO node_endpoints SELECT 'legacy_'||id,COALESCE(json_extract(effective_json,'$.name'),id),json_object('address',COALESCE(json_extract(effective_json,'$.address'),''),'port',COALESCE(json_extract(effective_json,'$.port'),0),'sni',COALESCE(json_extract(effective_json,'$.sni'),''),'host',COALESCE(json_extract(effective_json,'$.host'),''),'tls',json(CASE WHEN json_extract(effective_json,'$.tls') THEN 'true' ELSE 'false' END),'alpn',json(COALESCE(json_extract(effective_json,'$.alpn'),'[]'))),enabled,0,updated_at,updated_at FROM nodes;
INSERT INTO node_profiles(id,inbound_id,endpoint_id,name,source_type,enabled,created_at,updated_at) SELECT n.id,i.id,'legacy_'||n.id,COALESCE(json_extract(n.effective_json,'$.name'),n.id),'discovered',n.enabled,n.updated_at,n.updated_at FROM nodes n JOIN catalog_inbounds i ON i.instance_id=n.instance_id AND i.tag=n.inbound_tag AND i.protocol=n.protocol;
UPDATE node_profiles SET overrides_json=COALESCE((SELECT json_group_object(j.key,json_object('mode','set','value',json(CASE j.type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'array' THEN j.value WHEN 'object' THEN j.value ELSE json_quote(j.value) END))) FROM nodes n,json_each(n.overrides_json) j WHERE n.id=node_profiles.id AND j.key IN ('protocol','address','port','sni','host','path','service_name','public_key','short_id','fingerprint','flow','method','transport','tls','reality','xhttp_mode','alpn')),'{}');
CREATE TABLE node_groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE node_group_members(group_id TEXT NOT NULL REFERENCES node_groups(id) ON DELETE CASCADE,node_id TEXT NOT NULL REFERENCES node_profiles(id),sort_order INTEGER NOT NULL,PRIMARY KEY(group_id,node_id));
CREATE TABLE subscribers(id TEXT PRIMARY KEY,name TEXT NOT NULL,external_ref TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE subscriber_credentials(id TEXT PRIMARY KEY,subscriber_id TEXT NOT NULL REFERENCES subscribers(id),inbound_id TEXT REFERENCES catalog_inbounds(id),manual_node_id TEXT REFERENCES node_profiles(id),credential_id TEXT NOT NULL REFERENCES credential_material(id),enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(subscriber_id,inbound_id),UNIQUE(subscriber_id,manual_node_id),CHECK((inbound_id IS NOT NULL AND manual_node_id IS NULL) OR (inbound_id IS NULL AND manual_node_id IS NOT NULL)));
CREATE TABLE catalog_subscriptions(id TEXT PRIMARY KEY,subscriber_id TEXT NOT NULL REFERENCES subscribers(id),name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,token_version INTEGER NOT NULL DEFAULT 1,enabled INTEGER NOT NULL DEFAULT 1,expires_at TEXT,format TEXT NOT NULL,options_json TEXT NOT NULL DEFAULT '{}',last_access_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE catalog_subscription_nodes(subscription_id TEXT NOT NULL REFERENCES catalog_subscriptions(id) ON DELETE CASCADE,node_id TEXT NOT NULL REFERENCES node_profiles(id),sort_order INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(subscription_id,node_id));
CREATE TABLE catalog_subscription_groups(subscription_id TEXT NOT NULL REFERENCES catalog_subscriptions(id) ON DELETE CASCADE,group_id TEXT NOT NULL REFERENCES node_groups(id),sort_order INTEGER NOT NULL,PRIMARY KEY(subscription_id,group_id));
CREATE TABLE subscription_access_logs(id INTEGER PRIMARY KEY,subscription_id TEXT REFERENCES catalog_subscriptions(id) ON DELETE SET NULL,format TEXT NOT NULL,accessed_at TEXT NOT NULL,status_code INTEGER NOT NULL,error_code TEXT NOT NULL,user_agent TEXT NOT NULL,client_ip_hash TEXT NOT NULL);
CREATE INDEX subscription_access_time ON subscription_access_logs(accessed_at);
CREATE TABLE catalog_sync_runs(id INTEGER PRIMARY KEY,instance_id INTEGER REFERENCES instances(id),config_hash TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,summary_json TEXT NOT NULL,created_at TEXT NOT NULL);
INSERT INTO settings(key,value) VALUES('subscription_catalog','{"base_url":"","default_format":"mihomo","update_interval":24,"sync_interval_seconds":300,"log_retention_days":30,"rate_per_minute":60,"default_sort":"explicit"}');
